// generated by plugin/scripts/build.mjs from cli/src (piezas 0.7.4); do not edit by hand
// Part of the piezas CLI (see index.js): the quality scan.
//
// A second, independent look at the work before a build step is called done,
// run in the owner's own AI tool (it spends their AI allowance, so it never
// runs until the owner says yes). docs/quality-scan-spec.md is the design.
//
//   consent (owner reply only) -> packet + scanner prompt + one-time code
//   -> the scan, in a separate context (a subagent / a fresh session)
//   -> findings file -> verdict: .piezas/quality-attestation.json (24h)
//   -> fix and scan again, at most 3 rounds -> the deploy check.
//
// Files (in .piezas/):
//   quality-scan/packet.md      what the scanner reads (CLI-written, guarded)
//   quality-scan/prompt.md      the scanner's instructions (CLI-written, guarded)
//   quality-scan/scan-state.json the waiting scan, its code, the round count
//                               (CLI-written, guarded)
//   quality-scan/baseline.json  the files as of the last scan, for "what
//                               changed since" (CLI-written, guarded)
//   quality-scan/findings.json  the scanner's answer (the one file the AI writes)
//   quality-attestation.json    the result the deploy checks (CLI-written, guarded)
// The owner's decisions (the on/off setting, accepted findings) are owner
// records, kept with "deploy anyway" (guards.js appendOwnerRecord).
//
// Owner-facing words live in QUALITY_TEXT, scanned for jargon by a test; the
// word "review" and "audit" never appear where the owner reads.
import { execFileSync } from 'child_process';
import { existsSync, mkdirSync, readFileSync, realpathSync, rmSync, statSync, writeFileSync } from 'fs';
import { createHash, randomBytes } from 'crypto';
import { dirname, join, relative, sep } from 'path';
import { fileURLToPath } from 'url';
import {
  QUALITY_ATTESTATION_FILE,
  QUALITY_FINDINGS_FILE,
  QUALITY_SCAN_DIR,
  STATE_DIR,
} from './constants.js';
// Functions only, used at call time: the import cycles with these are safe.
import { HANDS_BACK, appendOwnerRecord, deployRecordRoot, ownerRecords } from './guards.js';
import { SPEC_FILE, findProjectRoot, loadState, toPosix } from './protocol.js';
import {
  TEST_RUN_FILE,
  fingerprintFiles,
  lastAssistantText,
  readScenarios,
  readTestAttestation,
  specFingerprint,
} from './testgate.js';

// ===========================================================================
// Constants
// ===========================================================================

export const QUALITY_VERSION = 1;
export const QUALITY_SETTINGS = ['on', 'off', 'before-publishing'];
// The fix loop's budget (decided 2026-10-26): after this many scans in one
// round of work, "done" goes through with what is still open.
export const QUALITY_MAX_ROUNDS = 3;
// Like the test record: a day.
export const QUALITY_MAX_AGE_MS = 24 * 60 * 60 * 1000;
export const QUALITY_SEVERITIES = ['high', 'medium', 'low'];
export const QUALITY_MAX_FINDINGS = 20;
export const QUALITY_PLAIN_MAX = 300;
// How many times in a row "done" is held for the same waiting scan before it
// goes through with a note (the AI tool could not run it).
export const QUALITY_MAX_HOLDS = 2;
export const QUALITY_PACKET_FILE = 'packet.md';
export const QUALITY_PROMPT_FILE = 'prompt.md';
export const QUALITY_STATE_FILE = 'scan-state.json';
export const QUALITY_BASELINE_FILE = 'baseline.json';
// Files the scan folder may hold that only the CLI writes.
export const QUALITY_GUARDED_FILES = [QUALITY_PACKET_FILE, QUALITY_PROMPT_FILE, QUALITY_STATE_FILE, QUALITY_BASELINE_FILE];
export const QUALITY_ATTESTATION_REL = `${STATE_DIR}/${QUALITY_ATTESTATION_FILE}`;
export const QUALITY_FINDINGS_REL = `${STATE_DIR}/${QUALITY_SCAN_DIR}/${QUALITY_FINDINGS_FILE}`;
const PACKET_FILE_MAX = 40 * 1024;
const PACKET_TOTAL_MAX = 300 * 1024;

// ===========================================================================
// Owner-facing words. Everything a business owner reads (directly, or relayed
// by their AI tool). Never "review" or "audit"; no file names, no jargon.
// ===========================================================================

const things = (n) => (n === 1 ? '1 thing' : `${n} things`);

