  acceptedMark: '(you accepted this)',
  fixedLine: (fixed, of) => `Fixed and re-checked: ${fixed} of ${of}.`,
  openHint: 'Say "accept" and the number (for example "accept 2"), or "accept all", to go on without fixing one. Otherwise they get fixed and checked again.',
  stopped: (rounds) => `Quality scan: stopped after ${rounds} rounds of fixes. Still open:`,
  stoppedHint: 'Say "accept" and the number (or "accept all") to go on without it.',
  notRun: 'The quality scan could not run this time, so this step was not checked. It will try again after the next change.',
  settingOn: 'Quality scan: on. It runs before each step is called done.',
  settingOff: 'Quality scan: off. Say "quality scan on" any time to turn it on.',
  settingBeforePublishing: 'Quality scan: on, before publishing only.',
  settingUnset: 'Quality scan: not turned on for this app yet.',
  // Between the AI's rounds: one line for the owner, no question.
  checking: 'Checking the app… running the quality scan.',
  fixing: (n, round) => `Checking the app… the quality scan found ${things(n)} to fix; your AI tool is fixing ${n === 1 ? 'it' : 'them'} (round ${round} of ${QUALITY_MAX_ROUNDS}).`,
  // In the one pause, after the AI's rounds.
  left: (n) => `${n === 1 ? '1 thing' : `${n} things`} the quality scan found that your AI tool couldn't fix:`,
