  acceptSaid: (list) => `Got it. ${QUALITY_TEXT.accepted(list)}`,
  acceptSayWhich: 'Say which one to accept by its number, for example "accept 2" (or "accept 1 3", or "accept all").',
  acceptNothingOpen: "That didn't match anything on the list: the last quality scan has nothing left to accept.",
