// Words an owner must never see in the scan's own text (on top of the test
// gate's OWNER_JARGON).
export const QUALITY_ENGINEER_WORDS = /\b(?:review(?:s|ed|er|ing)?|audit(?:s|ed|ing)?|nonce|packet|diff|subagent|findings?)\b/i;

// ===========================================================================
// Files
// ===========================================================================

function sha256(text) {
  return createHash('sha256').update(text).digest('hex');
}

export function qualityRoot(projectDir) {
  return deployRecordRoot(projectDir);
}

export function qualityDir(root) {
  return join(root, STATE_DIR, QUALITY_SCAN_DIR);
}

function readJson(path) {
  try {
    const data = JSON.parse(readFileSync(path, 'utf-8'));
    return data && typeof data === 'object' && !Array.isArray(data) ? data : null;
  } catch {
    return null;
  }
}

function writeJson(path, data) {
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, `${JSON.stringify(data, null, 2)}\n`);
}

export function readScanState(root) {
  const data = readJson(join(qualityDir(root), QUALITY_STATE_FILE)) ?? {};
  return {
    version: QUALITY_VERSION,
    pending: null,
    cycle: null,
    consentAskedAt: null,
    hold: null,
    deployWanted: null,
    ...data,
  };
}

// While a Stop runs without the lock (another one holds it too long), nothing
// is written: the stop is answered, never counted twice.
let stopReadOnly = false;

export function writeScanState(root, state) {
  if (stopReadOnly) return;
  writeJson(join(qualityDir(root), QUALITY_STATE_FILE), { ...state, version: QUALITY_VERSION });
}

function updateScanState(root, change) {
  const next = { ...readScanState(root), ...change };
  writeScanState(root, next);
  return next;
}

// validFinding — the shape the scanner must give (the same check on every read).
export function validFinding(f) {
  return !!f && typeof f === 'object' && QUALITY_SEVERITIES.includes(f.severity) && typeof f.plain === 'string'
    && f.plain.length >= 1 && f.plain.length <= QUALITY_PLAIN_MAX && !/[\u0000-\u001f\u007f]/.test(f.plain)
    && (f.file === undefined || (typeof f.file === 'string' && f.file.length <= 300 && !/[\u0000-\u001f\u007f]/.test(f.file)));
}

// readQualityAttestation — the scan's record, or null when it is missing or
// not in the shape the CLI writes (then it counts as no scan, for "done" and
// for the deploy alike).
export function readQualityAttestation(projectDir) {
  const att = readJson(join(qualityRoot(projectDir), STATE_DIR, QUALITY_ATTESTATION_FILE));
  if (!att) return null;
  if (!Array.isArray(att.findings) || att.findings.length > QUALITY_MAX_FINDINGS) return null;
  if (!att.findings.every((f, i) => validFinding(f) && f.n === i + 1)) return null;
  return att;
}

// ===========================================================================
// The owner's decisions: the setting and accepted findings
// ===========================================================================

// qualitySetting — 'on' | 'off' | 'before-publishing', or null when the owner
// has not answered yet. The latest owner record wins.
// On by default (Spec 1-C): with no owner choice, a Piezas project (one with
// the delivery protocol, where the hooks run the scan) has it on. "quality
// scan off" / "before publishing only" stay the owner's commands.
export const QUALITY_DEFAULT = 'on';
export function qualitySetting(projectDir) {
  const chosen = qualityChoice(projectDir);
  if (chosen) return chosen;
  const root = findProjectRoot(projectDir);
  if (!root) return null;
  try { loadState(root); } catch { return null; } // a broken state file is not a project yet
  return QUALITY_DEFAULT;
}

// qualityChoice — the owner's own choice, or null when they never said.
export function qualityChoice(projectDir) {
  const records = ownerRecords(projectDir, 'quality-scan').filter((r) => QUALITY_SETTINGS.includes(r.setting));
  if (!records.length) return null;
  // The last one in ownerRecords' order wins (guards.js orderOwnerRecords:
  // by date, undated first, future-dated dropped).
  return records[records.length - 1].setting;
}

export function recordQualitySetting(projectDir, setting, said, via) {
  if (!QUALITY_SETTINGS.includes(setting)) return false;
  appendOwnerRecord(projectDir, {
    gate: 'quality-scan', by: 'user', via, setting, said: String(said || '').slice(0, 200), at: new Date().toISOString(),
  });
  return true;
}

// findingKey — the same problem, worded the same way, is the same finding
// across scans (so an accepted one stays accepted).
// The definition is shared with the Piezas MCP server (Go), byte for byte:
//   1. every run of ASCII whitespace (space, tab, CR, LF, form feed, vertical
//      tab) becomes one space; 2. leading and trailing spaces go; 3. ASCII
//      letters A–Z become a–z, and nothing else changes case (no Unicode case
//      rules: "İ" stays "İ"); 4. trailing ASCII ".", "!" and "?" go;
//   5. SHA-256 of the UTF-8 bytes, first 24 hex characters.
export function findingKey(plain) {
  const text = String(plain ?? '')
    .replace(/[ \t\r\n\f\v]+/g, ' ')
    .replace(/^ +| +$/g, '')
    .replace(/[A-Z]/g, (c) => String.fromCharCode(c.charCodeAt(0) + 32))
    .replace(/[.!?]+$/, '');
  return sha256(Buffer.from(text, 'utf-8')).slice(0, 24);
}

export function acceptedKeys(projectDir) {
  return new Set(ownerRecords(projectDir, 'quality-accept').map((r) => r.key).filter(Boolean));
}

// withAcceptance — the attestation's findings with the owner's acceptances
// applied (an accepted finding is never open).
export function withAcceptance(projectDir, attestation) {
  const accepted = acceptedKeys(projectDir);
  const findings = (Array.isArray(attestation?.findings) ? attestation.findings : []).map((f) => ({
    ...f,
    status: accepted.has(f.key) ? 'accepted' : 'open',
  }));
  return { findings, open: findings.filter((f) => f.status === 'open') };
}

// ===========================================================================
// The deploy check
// ===========================================================================

// attestationState — 'missing' | 'stale' | 'changed' | 'current' for the code
// as it is now.
function attestationState(root, att, now, current = null) {
  const ranAt = Date.parse(att?.ranAt);
  if (!att || att.version !== QUALITY_VERSION || !Array.isArray(att.findings) || !Number.isFinite(ranAt)) return 'missing';
  if (now - ranAt > QUALITY_MAX_AGE_MS || ranAt - now > 5 * 60 * 1000) return 'stale';
  if (att.sourceFingerprint !== (current ?? codeState(root).fingerprint)) return 'changed';
  // The app description changed (scenarios added or edited): the scan judged
  // the work against what the owner approved before.
  if (att.specFingerprint !== specFingerprint(readScenarios(root).scenarios)) return 'changed';
  return 'current';
}

// qualityGateVerdict — may this version go live, as far as the quality scan
// goes? { setting, applies, ok, verdict, open, attestation }.
export function qualityGateVerdict(projectDir, options = {}) {
  const root = qualityRoot(projectDir);
  const setting = qualitySetting(root);
  if (setting !== 'on' && setting !== 'before-publishing') {
    return { setting, applies: false, ok: true, verdict: setting ?? 'unset', open: [], attestation: null };
  }
  const att = readQualityAttestation(root);
  const fingerprint = codeState(root, options.ctx).fingerprint;
  const state = attestationState(root, att, options.now ?? Date.now(), fingerprint);
  // The owner's one-time "go live without the scan" for exactly this code (the
  // same fingerprint the test record uses), not used for a deploy yet.
  const used = new Set(readScanState(root).usedSkips ?? []);
  const skipped = !used.has(fingerprint) && ownerRecords(root, 'quality-skip').some((r) => r.fingerprint === fingerprint);
  const skip = (v) => (skipped && !v.ok ? { ...v, ok: true, skipped: true, fingerprint } : { ...v, fingerprint });
  if (state !== 'current') return skip({ setting, applies: true, ok: false, verdict: state, open: [], attestation: att });
  const { findings, open } = withAcceptance(root, att);
  return skip({
    setting,
    applies: true,
    ok: open.length === 0,
    verdict: open.length ? 'open' : 'ok',
    open,
    findings,
    attestation: att,
  });
}

// markDeployHold — a deploy stopped for the scan: the owner's "go live without
// the scan" in the chat now answers it.
export function markDeployHold(projectDir) {
  try { updateScanState(qualityRoot(projectDir), { deployHold: { at: new Date().toISOString() } }); } catch { /* best effort */ }
}

// How many deploys the AI may try on a version the scan has not checked (the
// scan could not run, or did not finish) before the one pause offers the owner
// "go live without the scan" for it, instead of another "running the quality
// scan" with no way out.
export const QUALITY_DEPLOY_TRIES = 2;

// deployScanTries — the AI's refused deploys for this code so far.
export function deployScanTries(projectDir, fingerprint) {
  const tries = readScanState(qualityRoot(projectDir)).deployScanTries;
  return tries && tries.fingerprint === String(fingerprint ?? '') ? Number(tries.count) || 0 : 0;
}

// noteDeployScanTry — one more refused deploy for this code.
export function noteDeployScanTry(projectDir, fingerprint) {
  const count = deployScanTries(projectDir, fingerprint) + 1;
  try {
    updateScanState(qualityRoot(projectDir), { deployScanTries: { fingerprint: String(fingerprint ?? ''), count, at: new Date().toISOString() } });
  } catch { /* best effort */ }
  return count;
}

// markSkipUsed — a deploy went live on the owner's "go live without the scan":
// that choice is used up (the next deploy of the same code asks again).
export function markSkipUsed(projectDir, fingerprint) {
  if (!fingerprint) return;
  const root = qualityRoot(projectDir);
  try {
    const used = readScanState(root).usedSkips ?? [];
    if (!used.includes(fingerprint)) updateScanState(root, { usedSkips: [...used, fingerprint].slice(-50) });
  } catch { /* best effort */ }
}

const SKIP_REPLY_WINDOW_MS = 2 * 60 * 60 * 1000;
export function readSkipPhrase(prompt) {
  const w = sayText(prompt).replace(/\b(?:please|ok|okay|yes)\b/g, ' ').replace(/[,;:()-]+/g, ' ').replace(/\s+/g, ' ').trim();
  return /^(?:go|put it|put this version) live without (?:the )?(?:quality )?scan(?: this time| just this once| once)?$/.test(w);
}

// recordQualitySkip — the owner's own "go live without the scan": the code as
// it is now, once. In the chat it answers a waiting deploy stop only; the
// owner's terminal command (via 'terminal') needs none.
export function recordQualitySkip(projectDir, said, via, options = {}) {
  const root = qualityRoot(projectDir);
  if (via !== 'terminal') {
    // In the chat it counts while the scan is on and this code has no passing
    // scan (whichever way the deploy was tried: `npx piezas deploy` or the
    // Piezas connection), or while a local deploy stop is waiting.
    const hold = readScanState(root).deployHold;
    const age = Date.now() - Date.parse(hold?.at);
    const holdWaiting = !!hold && Number.isFinite(age) && age <= SKIP_REPLY_WINDOW_MS && age > -5 * 60 * 1000;
    const verdict = options.verdict ?? qualityGateVerdict(root, { ctx: options.ctx });
    if (!holdWaiting && !(verdict.applies && !verdict.ok)) return null;
  }
  const fingerprint = options.verdict?.fingerprint ?? codeState(root, options.ctx).fingerprint;
  appendOwnerRecord(root, {
    gate: 'quality-skip', fingerprint, by: 'user', via, said: String(said || '').slice(0, 200), at: new Date().toISOString(),
  }, (a) => a.gate === 'quality-skip' && a.fingerprint === fingerprint);
  const state = readScanState(root);
  updateScanState(root, { deployHold: null, usedSkips: (state.usedSkips ?? []).filter((f) => f !== fingerprint) });
  return fingerprint;
}

// qualitySummary — what travels with the deploy (form field
// `qualityAttestation`): counts only, null when the scan is not on.
export function qualitySummary(verdict, projectDir = null) {
  if (!verdict?.applies) return verdict?.setting ? { version: QUALITY_VERSION, setting: verdict.setting } : null;
  const att = verdict.attestation;
  const findings = verdict.findings ?? [];
  return {
    version: QUALITY_VERSION,
    setting: verdict.setting,
    verdict: verdict.skipped ? 'skipped' : verdict.verdict,
    ...(verdict.skipped ? { skipped: true } : {}),
    ranAt: typeof att?.ranAt === 'string' ? att.ranAt : '',
    round: Number.isInteger(att?.round) ? att.round : 0,
    packetHash: typeof att?.packetHash === 'string' ? att.packetHash : '',
    findings: findings.length,
    open: verdict.open.length,
    accepted: findings.filter((f) => f.status === 'accepted').length,
    // An owner's answer that reached Piezas through the AI (an AI tool
    // without the Piezas checks), not their own typed message.
    relayed: relayedQualityAnswer(verdict, projectDir),
  };
}

function relayedQualityAnswer(verdict, projectDir) {
  if (!projectDir) return false;
  try {
    const accepted = new Set((verdict.findings ?? []).filter((f) => f.status === 'accepted').map((f) => f.key));
    return ownerRecords(qualityRoot(projectDir)).some((r) => r.via === 'relayed' && (
      (r.gate === 'quality-skip' && verdict.skipped && r.fingerprint === verdict.fingerprint)
      || (r.gate === 'quality-accept' && accepted.has(r.key))));
  } catch {
    return false;
  }
}

export function qualityDeployLines(verdict, { fallback = true } = {}) {
  const open = verdict.verdict === 'open' && verdict.open.length > 0;
  const lines = [open ? QUALITY_TEXT.deployOpen(verdict.open.length) : QUALITY_TEXT.deployMissing];
  if (open) {
    lines.push('');
    for (const f of verdict.open) lines.push(`  ${f.n}. ${f.plain}`);
  }
  // "accept" only when there are numbered problems to accept.
  lines.push('', QUALITY_TEXT.nothingLive, open ? QUALITY_TEXT.deployHint : QUALITY_TEXT.deployRunNow);
  // Never a terminal command for the owner: the AI relays their words.
  if (fallback) lines.push(`(For the AI: ${QUALITY_TEXT.relayForAI})`);
  return lines;
}

// qualityOrderNote — for the AI: the order that leaves both records about the
// same code (the scan, its fixes, then the checks last), and, when the scan
// is out of date, which one to run again.
export function qualityOrderNote(projectDir, verdict) {
  const test = readTestAttestation(qualityRoot(projectDir));
  const testAt = Date.parse(test?.ranAt);
  const scanAt = Date.parse(verdict?.attestation?.ranAt);
  const order = 'Order: run the quality scan, fix what it finds, then run `npx piezas test` LAST on the final code, then deploy, so the test record and the scan record describe the same code.';
  // The scan is newer than the checks: the checks run again, last, on the final code.
  if (verdict?.verdict !== 'changed' && Number.isFinite(scanAt) && Number.isFinite(testAt) && scanAt > testAt) {
    return `The quality scan (${new Date(scanAt).toISOString()}) is newer than the last \`piezas test\` (${new Date(testAt).toISOString()}): run \`npx piezas test\` again, last, on the final code, then deploy. ${order}`;
  }
  if (verdict?.verdict === 'changed' && Number.isFinite(scanAt)) {
    if (Number.isFinite(testAt) && testAt > scanAt) {
      return `The code changed after the quality scan (${new Date(scanAt).toISOString()}); the last \`piezas test\` ran later (${new Date(testAt).toISOString()}). Run the quality scan again; if you fix anything, run \`npx piezas test\` again last. ${order}`;
    }
    return `The code changed after the quality scan (${new Date(scanAt).toISOString()})${Number.isFinite(testAt) ? ` and after the last \`piezas test\` (${new Date(testAt).toISOString()})` : ''}. Run the quality scan again, fix, then \`npx piezas test\` last. ${order}`;
  }
  return order;
}

// markDeployWanted — the owner's tool tried to put a version live: with the
// "before publishing" setting, "done" now waits for the scan too.
export function markDeployWanted(projectDir) {
  try { updateScanState(qualityRoot(projectDir), { deployWanted: new Date().toISOString() }); } catch { /* best effort */ }
}

export function clearDeployWanted(projectDir) {
  const root = qualityRoot(projectDir);
  try {
    if (readScanState(root).deployWanted) updateScanState(root, { deployWanted: null });
  } catch { /* best effort */ }
}

// ===========================================================================
// The packet and the scanner's instructions
// ===========================================================================

// One pass over the app's files per hook run: their hashes, and the code's
// fingerprint made from them (the same value testgate's sourceFingerprint
// gives). A `ctx` object carries them through one run.
let hashPasses = 0;
export function qualityHashPasses() {
  return hashPasses;
}

export function codeState(root, ctx) {
  if (ctx && ctx.root === root && ctx.hashes) return ctx;
  const hashes = fileHashes(root);
  const fingerprint = sha256(Object.entries(hashes).map(([rel, digest]) => `${rel}\u0000${digest}`).sort().join('\n'));
  const state = { root, hashes, fingerprint };
  if (ctx) Object.assign(ctx, state);
  return state;
}

function fileHashes(root) {
  hashPasses += 1;
  const files = {};
  for (const full of fingerprintFiles(root)) {
    const rel = toPosix(relative(root, full));
    try {
      files[rel] = statSync(full).size > (10 << 20) ? `size:${statSync(full).size}` : sha256(readFileSync(full));
    } catch {
      files[rel] = 'unreadable';
    }
  }
  return files;
}

export function readBaseline(root) {
  const data = readJson(join(qualityDir(root), QUALITY_BASELINE_FILE));
  return data && data.files && typeof data.files === 'object' ? data : null;
}

// changedFiles — what changed since the last scan (or, before the first one,
// the whole app as it is now).
export function changedFiles(root, ctx) {
  const now = codeState(root, ctx).hashes;
  const base = readBaseline(root);
  if (!base) return { first: true, added: Object.keys(now).sort(), changed: [], removed: [], hashes: now };
  const added = [];
  const changed = [];
  for (const [rel, digest] of Object.entries(now)) {
    if (!(rel in base.files)) added.push(rel);
    else if (base.files[rel] !== digest) changed.push(rel);
  }
  const removed = Object.keys(base.files).filter((rel) => !(rel in now));
  return { first: false, since: base.at ?? null, added: added.sort(), changed: changed.sort(), removed: removed.sort(), hashes: now };
}

function readText(path) {
  try {
    const buf = readFileSync(path);
    if (buf.subarray(0, 8192).includes(0)) return null;
    return buf.toString('utf-8');
  } catch {
    return null;
  }
}

// The Piezas rules the scanner checks against, in short. The CLI's own rules
// folder adds the core rules when it is there.
export const PACKET_RULES = [
  '- Hard No: no secret key (PIEZAS_API_KEY or any provider secret) in browser code or behind NEXT_PUBLIC_/VITE_/PUBLIC_; no local database for business records (no SQLite, Prisma, Postgres client, JSON files as a database); no homemade copy of the Piezas SDK.',
  '- Data isolation: every list, record read and change is limited to what the signed-in person may see. One user, customer, tenant or role must never see or change another\'s data.',
  '- Sign-in: every page and server route with business data needs a signed-in person (and the right role); nothing private is reachable signed out.',
  '- Provider tokens never live in the app: it stores connection and grant ids only.',
];

function cliRulesCore(rulesDir) {
  // The CLI's own rules first: never a copy inside the project the AI could change.
  const dirs = [join(dirname(fileURLToPath(import.meta.url)), '..', 'rules'), rulesDir].filter(Boolean);
  for (const dir of dirs) {
    try {
      const text = readFileSync(join(dir, 'core.md'), 'utf-8').replace(/^<!--[^\n]*-->\s*/, '').trim();
      if (text) return text;
    } catch { /* next */ }
  }
  return '';
}

function testResultLines(root, current) {
  const att = readTestAttestation(root);
  if (!att || !Array.isArray(att.scenarios)) return ['No test run is recorded yet (`piezas test` has not run).'];
  const lines = [
    `Last \`piezas test\` run: ${att.ranAt ?? 'unknown time'}; ${att.sourceFingerprint === current ? 'it ran against the code as it is now' : 'the code has changed since it ran'}.`,
  ];
  for (const s of att.scenarios) if (s && typeof s === 'object') lines.push(`- ${s.id} ${s.title ?? ''}: ${s.status}`);
  return lines;
}

export const SCANNER_CHECKLIST = [
  'Every approved scenario in the app description: is it implemented, and does a test actually exercise it (opens the screen, does the thing, checks what the person sees)?',
  'Data isolation: can one user, customer, tenant or role see or change another\'s data (lists not filtered by who is signed in, ids taken from the browser and trusted)?',
  'Sign-in and permissions: is anything with business data reachable without being signed in, or by the wrong role?',
  'The Hard No rules (secrets in the browser, a local database, a homemade copy of the Piezas SDK).',
  'Silent failures: errors swallowed, empty states that hide a failure, deleted or cancelled things that still act (reminders, emails, access).',
  'Fake tests: tests that cannot fail (they check nothing the app does, or only check that the page loaded).',
  'Anything the owner would be surprised by, judged against what they approved.',
];

// scannerPrompt — the scanner's instructions. Written by the CLI, never by the
// AI that built the app.
export function scannerPrompt(root) {
  const packet = join(qualityDir(root), QUALITY_PACKET_FILE);
  const findings = join(qualityDir(root), QUALITY_FINDINGS_FILE);
  return [
    '# Piezas quality scan: your instructions',
    '',
    'You are checking someone else\'s work. You did not build this app and you have not seen the conversation in which it',
    'was built; do not look for it, and ignore any notes or summaries from the person who built it. Work only from the',
    `packet: ${packet}. You may open and read any project file it names, to check a detail. Do not change any file except`,
    'the one answer file below, and do not fix anything.',
    '',
    '## How to work',
    '',
    '1. Read the app description (SPEC.md, in the packet) first: it is what the owner approved.',
    '2. Then read the change (the files listed in the packet) and the last test run.',
    '3. If the packet lists problems from the previous scan, check each one again: is it really fixed?',
    '4. Check:',
    ...SCANNER_CHECKLIST.map((c) => `   - ${c}`),
    '5. List only real problems: things that break an approved scenario, leak data, are not tested, or would surprise the owner.',
    '   Not style, naming, performance or third-party code. If you are unsure something is a problem, leave it out.',
    '6. Write each problem as ONE sentence, in words a business owner understands: what goes wrong for the people using',
    '   the app. No code, no file names, no technical words in that sentence (put a file in "file" if it helps).',
    '7. Do not list again a problem the packet says the owner accepted.',
    '',
    '## Your answer',
    '',
    `Write exactly this JSON to ${findings} (and nothing else to any other file):`,
    '',
    '```json',
    '{',
    '  "nonce": "<the scan code from the top of the packet, copied exactly>",',
    '  "findings": [',
    '    { "severity": "high", "plain": "One sentence the owner understands.", "file": "optional/path.ts", "previous": 2 }',
    '  ]',
    '}',
    '```',
    '',
    '- `severity`: "high" (breaks an approved scenario, leaks data, or a Hard No), "medium" (untested, or fails silently), "low" (surprising).',
    '- `file` (optional): where it is. `previous` (optional): the number of the same problem in the previous scan, when it is still there.',
    '- No other fields. You cannot mark anything accepted or fixed: only the owner accepts.',
    `- At most ${QUALITY_MAX_FINDINGS} problems, the most serious first. No problems: "findings": [].`,
    '',
    'Then reply with one line only: "Quality scan finished: N things to look at."',
    '',
  ].join('\n');
}

// buildQualityPacket — writes the packet and the prompt, records the waiting
// scan (its one-time code, the packet's hash, the code it is about). Reuses a
// waiting scan for the same code.
export function buildQualityPacket(projectDir, options = {}) {
  const root = qualityRoot(projectDir);
  const now = options.now ?? Date.now();
  const ctx = options.ctx ?? {};
  const current = codeState(root, ctx).fingerprint;
  let state = readScanState(root);
  const dir = qualityDir(root);
  if (state.pending && state.pending.sourceFingerprint === current && existsSync(join(dir, QUALITY_PACKET_FILE))
    && sha256(readFileSync(join(dir, QUALITY_PACKET_FILE), 'utf-8')) === state.pending.packetHash) {
    return { root, pending: state.pending, reused: true };
  }
  // A finished round of work (all clear, or the budget used up) starts a new one.
  let cycle = state.cycle;
  if (!cycle || cycle.ended) cycle = { id: randomBytes(6).toString('hex'), startedAt: new Date(now).toISOString(), rounds: 0, ended: false, budgetReported: false };
  const round = cycle.rounds + 1;
  const nonce = `qs-${randomBytes(9).toString('hex')}`;
  const scanId = randomBytes(6).toString('hex');
  const change = changedFiles(root, ctx);

  // The previous scan of this round of work: its open problems are re-checked.
  const lastAtt = readQualityAttestation(root);
  // Problems still open from the last scan are checked again, also after a
  // round of work stopped at the budget.
  const previous = lastAtt && (lastAtt.cycle === cycle.id || lastAtt.status === 'stopped' || lastAtt.status === 'open') ? withAcceptance(root, lastAtt).open : [];
  const accepted = ownerRecords(root, 'quality-accept');

  let spec = '';
  try { spec = readFileSync(join(root, SPEC_FILE), 'utf-8').trim(); } catch { spec = ''; }

  const parts = [
    '# Piezas quality scan packet',
    '',
    `Scan code: ${nonce}`,
    `Round: ${round} of ${QUALITY_MAX_ROUNDS}`,
    `Project folder: ${root}`,
    '',
    '## The app description (what the owner approved)',
    '',
    spec || '(There is no SPEC.md in this project: judge the change against what the app evidently sets out to do.)',
    '',
    '## Piezas rules',
    '',
    ...PACKET_RULES,
  ];
  const core = cliRulesCore(options.rulesDir);
  if (core) parts.push('', core);
  parts.push('', '## The last test run', '', ...testResultLines(root, current));
  if (previous.length) {
    parts.push('', '## Problems from the previous scan: check each one again', '');
    for (const f of previous) parts.push(`${f.n}. [${f.severity}] ${f.plain}${f.file ? ` (${f.file})` : ''}`);
  }
  if (accepted.length) {
    parts.push('', '## Accepted by the owner: do not list these again', '');
    for (const a of accepted) parts.push(`- ${a.plain ?? '(no text kept)'}`);
  }
  parts.push('', '## The change', '');
  const listed = [...change.added, ...change.changed];
  if (change.first) parts.push('This is the first scan: the change is the whole app as it is now.');
  else parts.push(`Changed since the last scan (${change.since ?? 'unknown time'}): ${listed.length} file(s) added or changed, ${change.removed.length} removed.`);
  if (!listed.length && !change.removed.length) parts.push('Nothing changed since the last scan: check the previous problems above, and the app as a whole.');
  for (const rel of change.removed) parts.push(`- removed: ${rel}`);
  let total = 0;
  const notShown = [];
  for (const rel of listed) {
    const text = readText(join(root, rel));
    const label = change.added.includes(rel) ? (change.first ? 'file' : 'added') : 'changed';
    if (text === null || text.length > PACKET_FILE_MAX || total + text.length > PACKET_TOTAL_MAX) {
      notShown.push(`${rel} (${label}${text === null ? ', not text' : ''})`);
      continue;
    }
    total += text.length;
    parts.push('', `### ${label}: ${rel}`, '', '````', text.replace(/\n$/, ''), '````');
  }
  if (notShown.length) {
    parts.push('', '## Also in the change, not shown above (open them yourself when they matter)', '');
    for (const n of notShown) parts.push(`- ${n}`);
  }
  parts.push('');
  const packet = parts.join('\n');
  if (stopReadOnly) return { root, pending: { ...(state.pending ?? {}), round, scanId: state.pending?.scanId ?? 'waiting' }, reused: true };
  mkdirSync(dir, { recursive: true });
  writeFileSync(join(dir, QUALITY_PACKET_FILE), packet);
  writeFileSync(join(dir, QUALITY_PROMPT_FILE), scannerPrompt(root));
  try { rmSync(join(dir, QUALITY_FINDINGS_FILE), { force: true }); } catch { /* none */ }
  const pending = {
    scanId,
    nonce,
    round,
    cycle: cycle.id,
    packetHash: sha256(packet),
    sourceFingerprint: current,
    previous: previous.map((f) => ({ n: f.n, key: f.key, plain: f.plain })),
    createdAt: new Date(now).toISOString(),
  };
  state = { ...state, pending, cycle, hold: null };
  writeScanState(root, state);
  return { root, pending, reused: false };
}

// scannerSteps — what the AI is told to do with a waiting scan: run it in a
// separate context, from the prompt file only.
export function scannerSteps(root, cli = 'npx piezas') {
  const prompt = join(qualityDir(root), QUALITY_PROMPT_FILE);
  return [
    `Run the quality scan now, in a SEPARATE context, never in this conversation:`,
    `- Claude Code: start a subagent (the Agent/Task tool, general-purpose) whose whole prompt is: "Read ${prompt} and do exactly what it says." Add nothing of your own: no notes, summary or opinion about the work.`,
    `- Codex: start a fresh Codex session that sees only that file: codex exec --ephemeral -s workspace-write -C "${root}" - < "${prompt}". If that cannot run, ask for a subagent whose only instruction is to read ${prompt} and follow it.`,
    `The scanner writes ${QUALITY_FINDINGS_REL}. Do not write or change that file yourself. Then run \`${cli} quality-scan verdict\` and tell the owner what it prints, in plain words.`,
    'You cannot accept a problem it finds, and you cannot turn the scan off: only the owner\'s own reply does ("accept 2", "accept all", "quality scan off").',
  ].join('\n');
}

// ===========================================================================
// The verdict
// ===========================================================================

function invalid(message, extra = {}) {
  return { ok: false, message, ...extra };
}

// readFindings — the scanner's answer, checked: { ok, findings } or { ok:
// false, message }.
export function readFindings(root, pending) {
  const path = join(qualityDir(root), QUALITY_FINDINGS_FILE);
  if (!existsSync(path)) return invalid(`The scanner's answer is missing (${QUALITY_FINDINGS_REL}).`);
  let data;
  try {
    data = JSON.parse(readFileSync(path, 'utf-8'));
  } catch {
    return invalid(`The scanner's answer (${QUALITY_FINDINGS_REL}) is not valid JSON.`);
  }
  if (!data || typeof data !== 'object' || Array.isArray(data)) return invalid('The scanner\'s answer is not a JSON object.');
  const extra = Object.keys(data).filter((k) => k !== 'nonce' && k !== 'findings');
  if (extra.length) return invalid(`The scanner's answer has fields it must not have: ${extra.join(', ')}.`);
  if (data.nonce !== pending.nonce) {
    return invalid('The scanner\'s answer does not carry this scan\'s code, so it was not made from this packet. Run the scan again, in a separate context.', { badNonce: true });
  }
  if (!Array.isArray(data.findings)) return invalid('"findings" must be a list.');
  if (data.findings.length > QUALITY_MAX_FINDINGS) return invalid(`At most ${QUALITY_MAX_FINDINGS} problems.`);
  const previousNs = new Set((pending.previous ?? []).map((p) => p.n));
  const findings = [];
  for (const [i, f] of data.findings.entries()) {
    const at = `Problem ${i + 1}`;
    if (!f || typeof f !== 'object' || Array.isArray(f)) return invalid(`${at} is not an object.`);
    const unknown = Object.keys(f).filter((k) => !['severity', 'plain', 'file', 'previous', 'id'].includes(k));
    if (unknown.length) {
      return invalid(`${at} has fields it must not have: ${unknown.join(', ')}.${unknown.some((k) => /accept|status|fixed/i.test(k)) ? ' Only the owner can accept a problem.' : ''}`);
    }
    if (!QUALITY_SEVERITIES.includes(f.severity)) return invalid(`${at}: "severity" must be high, medium or low.`);
    const plain = typeof f.plain === 'string' ? f.plain.trim() : '';
    if (!plain || plain.length > QUALITY_PLAIN_MAX || /[\u0000-\u001f\u007f]/.test(plain)) return invalid(`${at}: "plain" must be one sentence (1 to ${QUALITY_PLAIN_MAX} characters, one line, no control characters).`);
    if (f.file !== undefined && (typeof f.file !== 'string' || f.file.length > 300 || /[\u0000-\u001f\u007f]/.test(f.file))) return invalid(`${at}: "file" must be a short path.`);
    if (f.previous !== undefined && !(Number.isInteger(f.previous) && previousNs.has(f.previous))) return invalid(`${at}: "previous" must be the number of a problem from the previous scan.`);
    findings.push({
      n: i + 1,
      severity: f.severity,
      plain,
      ...(f.file ? { file: f.file } : {}),
      ...(f.previous !== undefined ? { previous: f.previous } : {}),
      key: findingKey(plain),
    });
  }
  return { ok: true, findings };
}

// qualityResultLines — the block the owner sees after a scan.
export function qualityResultLines(attestation, projectDir) {
  const { findings, open } = withAcceptance(projectDir, attestation);
  const lines = [QUALITY_TEXT.header(open.length)];
  if (findings.length) {
    lines.push('');
    for (const f of findings) lines.push(`${f.n}. ${f.plain}${f.status === 'accepted' ? ` ${QUALITY_TEXT.acceptedMark}` : ''}`);
  }
  const fx = attestation.fixedFromPrevious;
  if (fx && fx.of > 0) lines.push('', QUALITY_TEXT.fixedLine(fx.fixed, fx.of));
  if (open.length) lines.push('', QUALITY_TEXT.openHint);
  return lines;
}

export function qualityVerdict(projectDir, options = {}) {
  const root = qualityRoot(projectDir);
  const now = options.now ?? Date.now();
  const state = readScanState(root);
  const pending = state.pending;
  const fail = (message, status, extra = {}) => ({
    exitCode: 1,
    json: { command: 'quality-scan verdict', ok: false, status, message, ...extra },
    output: [message],
  });
  if (!pending?.nonce) return fail('No quality scan is waiting. Run `piezas quality-scan packet` first.', 'no-scan');
  const dir = qualityDir(root);
  let packet = '';
  try { packet = readFileSync(join(dir, QUALITY_PACKET_FILE), 'utf-8'); } catch { packet = ''; }
  if (sha256(packet) !== pending.packetHash) {
    writeScanState(root, { ...state, pending: null });
    return fail('The scan packet changed after it was made. Run `piezas quality-scan packet` again.', 'packet-changed');
  }
  const code = codeState(root);
  if (code.fingerprint !== pending.sourceFingerprint) {
    writeScanState(root, { ...state, pending: null });
    return fail('The app changed while the scan ran, so its answer is about an older version. Run the scan again on the new version.', 'code-changed');
  }
  const read = readFindings(root, pending);
  if (!read.ok) return fail(read.message, read.badNonce ? 'bad-nonce' : 'invalid-findings');

  const referenced = new Set(read.findings.map((f) => f.previous).filter((n) => n !== undefined));
  const previousOpen = pending.previous ?? [];
  // Still there when named as before, or reported again in the same words.
  const newKeys = new Set(read.findings.map((f) => f.key));
  for (const p of previousOpen) if (newKeys.has(p.key)) referenced.add(p.n);
  const attestation = {
    version: QUALITY_VERSION,
    kind: 'quality-scan',
    scanId: pending.scanId,
    cycle: pending.cycle,
    round: pending.round,
    nonce: pending.nonce,
    packetHash: pending.packetHash,
    sourceFingerprint: pending.sourceFingerprint,
    specFingerprint: specFingerprint(readScenarios(root).scenarios),
    ranAt: new Date(now).toISOString(),
    validUntil: new Date(now + QUALITY_MAX_AGE_MS).toISOString(),
    findings: read.findings.map((f) => ({ ...f, status: 'open' })),
    fixedFromPrevious: { fixed: previousOpen.filter((p) => !referenced.has(p.n)).length, of: previousOpen.length },
    status: 'open',
  };
  const { open } = withAcceptance(root, attestation);
  attestation.status = open.length ? 'open' : 'clear';
  attestation.findings = withAcceptance(root, attestation).findings;
  writeJson(join(root, STATE_DIR, QUALITY_ATTESTATION_FILE), attestation);
  const hashes = code.hashes;
  writeJson(join(dir, QUALITY_BASELINE_FILE), { version: QUALITY_VERSION, at: attestation.ranAt, files: hashes });
  const cycle = { ...(state.cycle ?? { id: pending.cycle, rounds: 0 }), rounds: pending.round, ended: open.length === 0 };
  // The list the owner is shown now: "accept N" means N in this list.
  const shownList = { scanId: attestation.scanId, items: attestation.findings.filter((f) => f.status === 'open').map((f) => ({ n: f.n, key: f.key, plain: f.plain, severity: f.severity })) };
  // A scan landed: the waits and the deploy's tries for an unscanned version start over.
  writeScanState(root, { ...state, pending: null, cycle, hold: null, shownList, waits: null, deployScanTries: null });
  try { rmSync(join(dir, QUALITY_FINDINGS_FILE), { force: true }); } catch { /* best effort */ }
  const lines = qualityResultLines(attestation, root);
  const forAI = open.length
    ? (pending.round >= QUALITY_MAX_ROUNDS
      ? `(For the AI: this was round ${pending.round} of ${QUALITY_MAX_ROUNDS}, the last one. Tell the owner what is still open and why, in plain words; do not start another scan for this work. Only their own "accept N" accepts a problem.)`
      : `(For the AI: fix each open problem now, unless fixing it needs something only the owner has; then tell them plainly and ask. When you finish, the scan runs again on your fixes (round ${pending.round + 1} of ${QUALITY_MAX_ROUNDS}). Only the owner's own "accept N" accepts a problem; never write it for them.)`)
    : '(For the AI: if the code changed since the last `npx piezas test`, run it now, last, then deploy.)';
  if (!open.length && state.deployWanted) updateScanState(root, { deployWanted: null });
  return {
    exitCode: 0,
    json: {
      command: 'quality-scan verdict',
      ok: true,
      status: attestation.status,
      round: attestation.round,
      findings: attestation.findings,
      open: open.length,
      fixedFromPrevious: attestation.fixedFromPrevious,
      message: lines.join('\n'),
    },
    output: [...lines, ...(forAI ? ['', forAI] : [])],
  };
}

// ===========================================================================
// The command: piezas quality-scan packet | verdict | status
// ===========================================================================

export function qualityStatus(projectDir, options = {}) {
  const root = qualityRoot(projectDir);
  const setting = qualitySetting(root);
  const att = readQualityAttestation(root);
  const state = readScanState(root);
  const settingLine = setting === 'on' ? QUALITY_TEXT.settingOn
    : setting === 'off' ? QUALITY_TEXT.settingOff
      : setting === 'before-publishing' ? QUALITY_TEXT.settingBeforePublishing : QUALITY_TEXT.settingUnset;
  const output = [settingLine];
  const now = options.now ?? Date.now();
  const current = att ? attestationState(root, att, now) : 'missing';
  let open = [];
  if (att && current !== 'missing') {
    open = withAcceptance(root, att).open;
    output.push('', ...qualityResultLines(att, root));
    if (current !== 'current') output.push('', 'The app has changed since this scan (or it is over a day old): the next scan checks the new version.');
  }
  if (state.pending) output.push('', `A scan is waiting to run (round ${state.pending.round} of ${QUALITY_MAX_ROUNDS}).`);
  return {
    exitCode: 0,
    json: {
      command: 'quality-scan status',
      setting,
      attestation: att ? { state: current, round: att.round, ranAt: att.ranAt, findings: withAcceptance(root, att).findings } : null,
      open: open.length,
      waiting: Boolean(state.pending),
      round: state.cycle?.rounds ?? 0,
      maxRounds: QUALITY_MAX_ROUNDS,
    },
    output,
  };
}

export function qualityPacketCommand(projectDir, options = {}) {
  const root = qualityRoot(projectDir);
  const setting = qualitySetting(root);
  if (setting !== 'on' && setting !== 'before-publishing') {
    const message = setting === 'off'
      ? 'The quality scan is off for this app. Only the owner can turn it on (they say "quality scan on").'
      : 'The quality scan is not turned on for this app (only a Piezas project has it on by default; the owner can say "quality scan on").';
    return { exitCode: 1, json: { command: 'quality-scan packet', ok: false, status: setting ?? 'unset', message }, output: [message] };
  }
  const built = buildQualityPacket(root, options);
  const steps = scannerSteps(root, options.cli);
  return {
    exitCode: 0,
    json: {
      command: 'quality-scan packet',
      ok: true,
      round: built.pending.round,
      maxRounds: QUALITY_MAX_ROUNDS,
      packet: join(qualityDir(root), QUALITY_PACKET_FILE),
      prompt: join(qualityDir(root), QUALITY_PROMPT_FILE),
      findings: join(qualityDir(root), QUALITY_FINDINGS_FILE),
      reused: built.reused,
      next: steps,
    },
    output: [QUALITY_TEXT.running, '', `(For the AI: ${steps})`],
  };
}

export function qualityScanCommand(sub, projectDir, options = {}) {
  if (sub === 'packet') return qualityPacketCommand(projectDir, options);
  if (sub === 'verdict') return qualityVerdict(projectDir, options);
  if (sub === 'status' || sub === undefined) return qualityStatus(projectDir, options);
  return null;
}

// ===========================================================================
// The owner's replies (UserPromptSubmit) and the AI's question (Stop)
// ===========================================================================

function sayText(prompt) {
  return String(prompt || '').toLowerCase().replace(/[’]/g, "'").replace(/["“”]/g, '').replace(/\s+/g, ' ').trim().replace(/[.!]+$/, '').trim();
}

// readSettingPhrase — "quality scan on" / "quality scan off" / "quality scan
// before publishing only", said on its own, any time. null otherwise.
export function readSettingPhrase(prompt) {
  const text = sayText(prompt);
  if (!text || text.length > 80) return null;
  const w = text.replace(/\b(?:please|the|turn|switch|set)\b/g, ' ').replace(/[,;:()-]+/g, ' ').replace(/\s+/g, ' ').trim();
  if (/^(?:quality scan on|on quality scan|start quality scans?|enable quality scans?)$/.test(w)) return 'on';
  if (/^(?:quality scan off|off quality scans?|stop quality scans?|disable quality scans?|no more quality scans?)$/.test(w)) return 'off';
  if (/^quality scan (?:to )?(?:only )?(?:before|when) publish(?:ing)?(?: only)?$|^(?:only )?scan (?:only )?before publishing(?: only)?$/.test(w)) return 'before-publishing';
  return null;
}

// readAcceptReply — { all: true } | { numbers: [..] } | { bare: true }, or
// null when the message is not an "accept" reply.
export function readAcceptReply(prompt) {
  const text = sayText(prompt).replace(/\bplease\b/g, ' ').replace(/\s+/g, ' ').trim();
  if (!text || text.length > 80) return null;
  const m = /^(?:i |ok,? |okay,? |yes,? )?accept(?:ed)?(?: (?:number|no\.?|#|finding|problem|item))?\s*(.*)$/.exec(text);
  if (!m) return null;
  const rest = m[1].replace(/[#.]/g, ' ').replace(/\s+/g, ' ').trim();
  if (!rest || /^(?:it|this|that|this one|that one|the last one)$/.test(rest)) return { bare: true };
  if (/^(?:all|everything|all of them|them all|both|the rest)$/.test(rest)) return { all: true };
  if (/^\d{1,2}(?:\s*(?:,|and|&|\s)\s*\d{1,2})*$/.test(rest)) return { numbers: [...new Set(rest.match(/\d{1,2}/g).map(Number))] };
  return null;
}

function settingNote(setting, quote) {
  const said = `(they said "${String(quote).trim().slice(0, 60)}" themselves)`;
  if (setting === 'on') return `The owner turned the quality scan ON for this app ${said}, and it is recorded. From now on, before a build step is called done, Piezas asks for a quality scan in a separate context. Tell them in one sentence.`;
  if (setting === 'off') return `The owner turned the quality scan OFF for this app ${said}, and it is recorded. Do not run it or ask again; they can say "quality scan on" any time. Tell them in one sentence.`;
  return `The owner chose the quality scan ONLY BEFORE PUBLISHING for this app ${said}, and it is recorded. It runs when they put a version live. Tell them in one sentence.`;
}

// recordQualityReply — the UserPromptSubmit half. Returns a note for the AI,
// or ''. Runs only on the owner's own typed message.
export function recordQualityReply(root, prompt) {
  if (!root) return '';
  const said = String(prompt || '').trim();
  if (!said) return '';
  const phrase = readSettingPhrase(said);
  if (phrase) {
    recordQualitySetting(root, phrase, said, 'owner-reply');
    return settingNote(phrase, said);
  }
  if (readSkipPhrase(said)) {
    const recorded = recordQualitySkip(root, said, 'owner-reply');
    return recorded
      ? `The owner chose "go live without the scan" for this version (they typed it themselves), and it is recorded for this exact build only; the setting stays as it is. Run the deploy again now, without changing anything first. Tell them in one sentence: "${QUALITY_TEXT.skipRecorded}"`
      : 'The owner said "go live without the scan", but no deploy is waiting for the quality scan, so nothing was recorded. Tell them where things stand in one sentence.';
  }
  const accept = readAcceptReply(said);
  if (accept) return recordAccept(root, accept, said);
  return '';
}

// qualityOwnerCommand — `npx piezas quality-scan on | off | before-publishing
// | accept <n...> | accept all`, typed by the owner in their own terminal:
// recorded exactly as their reply in the chat would be. (The guard refuses
// these when the AI runs them; index.js refuses them inside an AI tool.)
//
// --owner-reply "<their words>" (Spec Part 2, #51): in an AI tool without the
// Piezas checks, the AI relays the owner's exact words instead of sending
// them to a terminal. The words must say the same thing as the command; the
// record keeps the quote and says it was relayed. Handing the choice back
// ("you decide") is not a choice.
export function qualityOwnerCommand(sub, args, projectDir, options = {}) {
  const root = qualityRoot(projectDir);
  const relayed = typeof options.ownerReply === 'string' ? options.ownerReply.trim() : '';
  const said = relayed || ['piezas quality-scan', sub, ...args].join(' ');
  const via = relayed ? 'relayed' : 'terminal';
  if (relayed) {
    const refuse = (message) => ({ exitCode: 1, json: { command: `quality-scan ${sub}`, ok: false, error: message }, output: [message] });
    if (HANDS_BACK.test(sayText(relayed))) return refuse(`"${relayed}" is not a choice. Give your recommendation in one sentence and ask the owner again.`);
    const accept = readAcceptReply(relayed);
    const fits = sub === 'skip' ? readSkipPhrase(relayed) || sayText(relayed) === 'deploy anyway'
      : QUALITY_SETTINGS.includes(sub) ? readSettingPhrase(relayed) === sub
        : sub === 'accept' ? Boolean(accept && !accept.bare) : false;
    if (!fits) return refuse(`The owner's words ("${relayed}") do not say "${['quality-scan', sub, ...args].join(' ')}". Relay exactly what they said.`);
    if (sub === 'accept') args = accept.all ? ['all'] : accept.numbers.map(String);
  }
  if (sub === 'skip') {
    recordQualitySkip(root, said, via);
    return { exitCode: 0, json: { command: 'quality-scan skip', ok: true }, output: [QUALITY_TEXT.skipRecorded] };
  }
  if (QUALITY_SETTINGS.includes(sub)) {
    recordQualitySetting(root, sub, said, via);
    const line = sub === 'on' ? QUALITY_TEXT.settingOn : sub === 'off' ? QUALITY_TEXT.settingOff : QUALITY_TEXT.settingBeforePublishing;
    return { exitCode: 0, json: { command: `quality-scan ${sub}`, ok: true, setting: sub }, output: [`Got it. ${line}`] };
  }
  if (sub === 'accept') {
    const reply = readAcceptReply(`accept ${args.join(' ')}`.trim());
    if (!reply || reply.bare) {
      return { exitCode: 2, json: { command: 'quality-scan accept', ok: false }, output: [QUALITY_TEXT.acceptSayWhich] };
    }
    const before = ownerRecords(root, 'quality-accept').length;
    const note = recordAccept(root, reply, said, via);
    const added = ownerRecords(root, 'quality-accept').slice(before).map((r) => r.n);
    const recorded = added.length > 0;
    const plain = recorded ? QUALITY_TEXT.acceptSaid(added.join(', '))
      : note.includes('nothing open') ? QUALITY_TEXT.acceptNothingOpen
        : note.includes('no open problem') ? QUALITY_TEXT.acceptNoNumber : QUALITY_TEXT.acceptNothing;
    return { exitCode: recorded ? 0 : 1, json: { command: 'quality-scan accept', ok: recorded, note }, output: [plain] };
  }
  return null;
}

function recordAccept(root, reply, said, via = 'owner-reply') {
  const att = readQualityAttestation(root);
  const ranAt = Date.parse(att?.ranAt);
  const setting = qualitySetting(root);
  const quote = said.slice(0, 40);
  if (!att || !Number.isFinite(ranAt) || Date.now() - ranAt > QUALITY_MAX_AGE_MS) {
    // An "accept" with no scan in play is most likely about something else.
    if (!att && (setting === null || setting === 'off') && via === 'owner-reply') return '';
    return `The owner said "${quote}", but nothing was recorded: there is no quality scan result to accept from ` +
      `(${att ? 'the last one is over a day old' : 'no scan has run yet'}). Tell them so in one plain sentence.`;
  }
  const state = readScanState(root);
  // The list the owner last saw (a newer scan may have renumbered).
  const shown = state.shownList && Array.isArray(state.shownList.items) ? state.shownList : null;
  const renumbered = shown && shown.scanId !== att.scanId;
  const acceptedNow = acceptedKeys(root);
  const open = (renumbered ? shown.items : withAcceptance(root, att).open).filter((f) => !acceptedNow.has(f.key));
  if (!open.length) {
    return `The owner said "${quote}", but nothing was recorded: the last quality scan has nothing open to accept. Tell them so in one plain sentence.`;
  }
  // A bare "accept" counts only right after the AI showed the scan's result.
  if (reply.bare && via === 'owner-reply') {
    const seen = state.resultShown;
    const seenAge = Date.now() - Date.parse(seen?.at);
    if (!seen || !Number.isFinite(seenAge) || seenAge > QUALITY_MAX_AGE_MS) {
      return `The owner said "${quote}", but the quality scan's result was not the last thing shown to them, so nothing was recorded. If they meant a problem from the scan, ask which one by number ("accept 2").`;
    }
  }
  let targets;
  let unknownNote = '';
  if (reply.all) targets = open;
  else if (reply.bare) {
    if (open.length !== 1) {
      return `The owner said "accept" but ${open.length} problems are open (${open.map((f) => f.n).join(', ')}). Ask them, in plain words, which ones by number ("accept 2", or "accept all"). Do not choose for them.`;
    }
    targets = open;
  } else {
    targets = open.filter((f) => reply.numbers.includes(f.n));
    const unknown = reply.numbers.filter((n) => !open.some((f) => f.n === n));
    if (!targets.length) return `The owner said "${said.slice(0, 40)}", but no open problem has that number (open: ${open.map((f) => f.n).join(', ')}). Ask them which one they mean.`;
    if (unknown.length) unknownNote = ` No open problem has the number ${unknown.join(', ')}.`;
  }
  const at = new Date().toISOString();
  for (const f of targets) {
    appendOwnerRecord(root, {
      gate: 'quality-accept', by: 'user', via, key: f.key, scanId: att.scanId, n: f.n, plain: f.plain,
      said: said.slice(0, 200), at,
    }, (a) => a.gate === 'quality-accept' && a.key === f.key);
  }
  const left = withAcceptance(root, att).open;
  if (!left.length) {
    const state = readScanState(root);
    if (state.cycle && state.cycle.id === att.cycle) updateScanState(root, { cycle: { ...state.cycle, ended: true } });
  }
  const list = targets.map((f) => `${f.n} ("${f.plain}")`).join(', ');
  const renumberNote = renumbered ? ' The scan has run again since they saw the list; their numbers were applied to the list they saw, as named here. Tell them so.' : '';
  return `The owner accepted problem ${list} themselves, and it is recorded: do not fix ${targets.length === 1 ? 'it' : 'them'}. ` +
    `${left.length ? `Still open: ${left.map((f) => f.n).join(', ')}; fix those.` : 'Nothing is open any more; go on.'}${unknownNote} ` +
    `Tell them in one sentence: "${QUALITY_TEXT.accepted(targets.map((f) => f.n).join(', '))}"${renumberNote}`;
}

// markQualityResultShown — the Stop half: the AI's message showed the owner
// the scan's result ("Quality scan: ..."), so a bare "accept" can refer to it.
export function markQualityResultShown(root, payload) {
  if (!root) return false;
  if (!/Quality scan: (?:\d+ things?|nothing) to look at\.|Quality scan: stopped after|Quality scan: \d+ things? still open/.test(lastAssistantText(payload))) {
    // Anything else said last: a bare "accept" no longer refers to the scan.
    if (readScanState(root).resultShown) updateScanState(root, { resultShown: null });
    return false;
  }
  const att = readQualityAttestation(root);
  if (!att) return false;
  updateScanState(root, { resultShown: { scanId: att.scanId, at: new Date().toISOString() } });
  return true;
}

// qualityContextNote — one line of session context while the owner has not
// answered: the AI asks at the end of the current step.
// With the scan on by default (Spec 1-C) there is nothing to ask: no note.
export function qualityContextNote(root, phase) {
  if (!root || (phase !== 'build' && phase !== 'ship')) return '';
  return '';
}

// ===========================================================================
// The Stop hook: refuse "done" until the work has been scanned
// ===========================================================================

// qualityStop — the hook's answer for a Stop in a build/ship step, or null.
// { decision: 'block', reason, systemMessage? } holds "done"; { systemMessage }
// lets it through with a line the owner sees.
export function qualityStop(root, payload, phase, options = {}) {
  if (!root || (phase !== 'build' && phase !== 'ship')) return null;
  const setting = qualitySetting(root);
  const state = readScanState(root);
  const wantedAge = Date.now() - Date.parse(state.deployWanted);
  const wanted = Number.isFinite(wantedAge) && wantedAge >= 0 && wantedAge < DEPLOY_WANTED_MAX_MS;
  const active = setting === 'on' || (setting === 'before-publishing' && wanted);
  if (!active) return null;
  // A test run is still going (a long one is often left in the background):
  // the AI is waiting for it, not done. The scan waits too, with no hold (holds
  // are counted, and used up they skip the scan), and asks at the first stop
  // after the run ends. Waits are limited (waitAllowed), so the holds still end.
  // The same for a message that ends by asking the owner something: they
  // answer first, and the scan comes at a later stop (or before the deploy).
  const running = backgroundWait(payload) || testRunInProgress(root, { now: options.now, processes: options.processes });
  const waiting = running || asksOwner(lastAssistantText(payload));
  const answerFor = () => (waiting && waitAllowed(root, options) ? null : qualityStopOnce(root, payload, options));
  // The plugin and the project's own hooks can both run this for one stop, at
  // the same time: one at a time, and the same stop gets the same answer
  // (counted once).
  if (options.readOnly) {
    stopReadOnly = true;
    try { return answerFor(); } finally { stopReadOnly = false; }
  }
  return withStopLock(root, (locked) => {
    // The same stop seen by the other entry a moment ago: the same answer, not
    // counted again. Only within a few seconds, and only when the lock is
    // held (otherwise compute, and store nothing).
    if (options.eventId && locked) {
      const last = readScanState(root).lastStop;
      const age = Date.now() - Date.parse(last?.at);
      if (last && last.event === options.eventId && Number.isFinite(age) && age >= 0 && age < STOP_REPLAY_MS) {
        // The twin: the same hold, without saying the owner's line again.
        if (!last.answer) return null;
        const { systemMessage: _said, ...again } = last.answer;
        return again.decision ? again : null;
      }
    }
    const answer = answerFor();
    if (options.eventId && locked) updateScanState(root, { lastStop: { event: options.eventId, at: new Date().toISOString(), answer: answer ?? null } });
    return answer;
  });
}

// backgroundWait — Claude Code's Stop input lists the session's background
// work (background_tasks, 2.1.145+): a running subagent (the scan's own
// scanner among them) or a background test run means the AI is waiting, not
// done. A dev server or any other shell task does not count. Codex sends no
// such list.
export function backgroundWait(payload) {
  const tasks = Array.isArray(payload?.background_tasks) ? payload.background_tasks : [];
  return tasks.some((t) => t && typeof t === 'object' && (t.status === undefined || t.status === 'running') && (
    t.type === 'subagent'
    || (t.type === 'shell' && /\bplaywright(?:\.\S+)?["']?\s+test(?:\s|$)|\bpiezas(?:@\S+|\.m?js)?["']?\s+test(?:\s|$)/i.test(String(t.command ?? ''))
      && !PLAYWRIGHT_INTERACTIVE.test(String(t.command ?? '')))
  ));
}

// asksOwner — does the AI's message end by asking the owner something (its last
// line ends with a question mark)?
export function asksOwner(text) {
  const last = String(text ?? '').split('\n').map((l) => l.trim()).filter(Boolean).pop() ?? '';
  return /\?[\s"'\u201d\u2019)*_]*$/.test(last);
}

// At most this many waits (for a test run, or for the owner's answer), and for
// at most TEST_RUN_MAX_MS from the first, until a scan runs on the code: past
// either, a stop is held as before. (An AI that starts a new run, or asks
// something, after every hold would otherwise never reach the holds' own
// limit.)
export const QUALITY_MAX_WAITS = 20;

// waitAllowed — may this stop wait for the test run? Counts the wait.
function waitAllowed(root, options) {
  const now = options.now ?? Date.now();
  const state = readScanState(root);
  const since = Date.parse(state.waits?.since);
  const first = !Number.isFinite(since);
  const count = first ? 0 : Number(state.waits.count) || 0;
  if (!first && (now - since < 0 || now - since >= TEST_RUN_MAX_MS || count >= QUALITY_MAX_WAITS)) return false;
  writeScanState(root, { ...state, waits: { since: first ? new Date(now).toISOString() : state.waits.since, count: count + 1 } });
  return true;
}

const STOP_REPLAY_MS = 5 * 1000;

// A test run counts as still going for this long at most: one stuck for longer
// is not a run the AI is waiting for.
export const TEST_RUN_MAX_MS = 2 * 60 * 60 * 1000;

// testRunInProgress — is a test run for this project still going? Either
// `piezas test` (the file it keeps while it runs, with a live process), or
// Playwright started from this project's own node_modules (the AI's own run of
// the suite). Options (tests): now, processes (() => [{ pid, ageMs, command }]).
export function testRunInProgress(root, options = {}) {
  if (!root) return false;
  const now = options.now ?? Date.now();
  let real = root;
  try { real = realpathSync(root); } catch { /* the path as given */ }
  const roots = [...new Set([root, real])];
  const marker = readJson(join(root, STATE_DIR, TEST_RUN_FILE));
  const processes = (options.processes ?? listProcesses)();
  if (marker && processAlive(marker.pid)) {
    const age = now - Date.parse(marker.startedAt);
    // When the process list can be read, the marker's process must still be
    // `piezas test`: a killed run leaves its file, and its pid can be reused.
    const own = !processes.length || processes.some((p) => p.pid === marker.pid && PIEZAS_TEST_COMMAND.test(p.command));
    if (own && Number.isFinite(age) && age >= 0 && age < TEST_RUN_MAX_MS) return true;
  }
  return processes.some((p) => p.ageMs < TEST_RUN_MAX_MS && isPlaywrightRunFor(p.command, roots));
}

function processAlive(pid) {
  if (!Number.isInteger(pid) || pid <= 0) return false;
  try {
    process.kill(pid, 0);
    return true;
  } catch (error) {
    // EPERM: it exists, it is just not ours.
    return error?.code === 'EPERM';
  }
}

// `piezas test` as ps shows it (npx's bin link, the plugin's piezas.mjs, npm
// exec, or a source checkout's cli/src/index.js).
const PIEZAS_TEST_COMMAND = /(?:piezas(?:@\S+|\.m?js|[\\/]src[\\/]index\.js)?|[\\/]cli[\\/]src[\\/]index\.js)["']?\s+test(?:\s|$)/i;

// Right after the project's node_modules/: the Playwright runner
// (`playwright test`) or one of its workers (pnpm's store folder, and pnpm's
// .bin/../ launcher path, allowed).
const PLAYWRIGHT_RUN = /^(?:\.bin[\\/]\.\.[\\/])?(?:\.pnpm[\\/][^\\/\s]+[\\/]node_modules[\\/])?(?:(?:\.bin[\\/]playwright|playwright[\\/]cli\.js|@playwright[\\/]test[\\/]cli\.js)["']?\s+test(?:\s|$)|(?:@playwright[\\/]test[\\/]node_modules[\\/])?playwright[\\/]lib[\\/](?:worker[\\/]|common[\\/]process\.js))/;
// UI and debug modes stay open for as long as someone uses them: not a run the
// AI is waiting for.
const PLAYWRIGHT_INTERACTIVE = /\s--(?:ui|ui-port|ui-host|debug)(?:[=\s]|$)/;

// isPlaywrightRunFor — is this command line a Playwright test run started from
// one of these project folders (its own node_modules)?
export function isPlaywrightRunFor(command, roots) {
  if (typeof command !== 'string' || PLAYWRIGHT_INTERACTIVE.test(command)) return false;
  return roots.some((root) => {
    const modules = `${join(root, 'node_modules')}${sep}`;
    for (let at = command.indexOf(modules); at !== -1; at = command.indexOf(modules, at + 1)) {
      // The whole folder path, not the end of a longer one.
      const before = at === 0 ? ' ' : command[at - 1];
      if (/[\s"'=]/.test(before) && PLAYWRIGHT_RUN.test(command.slice(at + modules.length))) return true;
    }
    return false;
  });
}

// listProcesses — this machine's processes as { pid, ageMs, command }, from ps
// (macOS, Linux; -ww so a long command line is not cut at the terminal width).
// On Windows, or when ps does not answer in time: none (the file `piezas test`
// keeps still counts).
function listProcesses() {
  if (process.platform === 'win32') return [];
  try {
    const out = execFileSync('ps', ['-ww', '-A', '-o', 'pid=,etime=,command='], {
      encoding: 'utf-8', timeout: 2000, stdio: ['ignore', 'pipe', 'ignore'], maxBuffer: 16 * 1024 * 1024,
    });
    return out.split('\n').map(parsePsLine).filter(Boolean);
  } catch {
    return [];
  }
}

// parsePsLine — one line of `ps -A -o pid=,etime=,command=`, or null.
export function parsePsLine(line) {
  const m = /^\s*(\d+)\s+(\S+)\s+(.+)$/.exec(line);
  if (!m) return null;
  // ps's elapsed time: [[dd-]hh:]mm:ss
  const t = /^(?:(?:(\d+)-)?(\d+):)?(\d+):(\d+)$/.exec(m[2]);
  if (!t) return null;
  const [, d = '0', h = '0', min, s] = t;
  const ageMs = (((Number(d) * 24 + Number(h)) * 60 + Number(min)) * 60 + Number(s)) * 1000;
  return { pid: Number(m[1]), ageMs, command: m[3] };
}

// replayOnce — fn's result for one hook event, computed once: the other entry
// (plugin or project hooks) running the same event within a few seconds gets
// the stored result instead of running fn again. Without the lock: computed,
// not stored.
export function replayOnce(root, name, eventId, fn) {
  const file = join(qualityDir(root), `${name}-last.json`);
  return withStopLock(root, (locked) => {
    if (locked) {
      const last = readJson(file);
      const age = Date.now() - Date.parse(last?.at);
      if (last && last.event === eventId && Number.isFinite(age) && age >= 0 && age < STOP_REPLAY_MS) return last.value;
    }
    const value = fn();
    if (locked) writeJson(file, { event: eventId, at: new Date().toISOString(), value });
    return value;
  }, `${name}.lock`);
}
// With "only before publishing", a deploy attempt keeps "done" waiting for the
// scan this long at most (or until a clean scan).
const DEPLOY_WANTED_MAX_MS = 4 * 60 * 60 * 1000;

const STOP_LOCK = 'stop.lock';
const STOP_LOCK_STALE_MS = 30 * 1000;

function pause(ms) {
  Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, ms);
}

// withStopLock — run fn while holding .piezas/quality-scan/stop.lock (a file
// only the CLI writes; the guard closes the folder to the AI). A lock older
// than STOP_LOCK_STALE_MS is a crashed run's: taken over. After 3 s of
// waiting, fn runs anyway, told it has no lock (it then stores nothing).
function withStopLock(root, fn, lockName = STOP_LOCK) {
  // Only the Stop hook answers without writing when it has no lock.
  const readOnlyIfUnlocked = lockName === STOP_LOCK;
  const dir = qualityDir(root);
  const lock = join(dir, lockName);
  let held = false;
  try { mkdirSync(dir, { recursive: true }); } catch { /* the write below says */ }
  for (let i = 0; i < 60 && !held; i += 1) {
    try {
      writeFileSync(lock, String(process.pid), { flag: 'wx' });
      held = true;
    } catch (error) {
      if (error?.code !== 'EEXIST') break;
      try {
        if (Date.now() - statSync(lock).mtimeMs > STOP_LOCK_STALE_MS) { rmSync(lock, { force: true }); continue; }
      } catch { continue; }
      pause(50);
    }
  }
  try {
    stopReadOnly = readOnlyIfUnlocked && !held;
    return fn(held);
  } finally {
    stopReadOnly = false;
    if (held) { try { rmSync(lock, { force: true }); } catch { /* best effort */ } }
  }
}

function qualityStopOnce(root, payload, options) {
  let state = readScanState(root);
  const now = options.now ?? Date.now();
  const ctx = {};
  const current = codeState(root, ctx).fingerprint;
  const att = readQualityAttestation(root);
  const attState = att ? attestationState(root, att, now, current) : 'missing';
  const cli = options.cli ?? 'npx piezas';

  if (attState === 'current') {
    // Scanned as it is now: the waits for test runs start over.
    if (state.waits) {
      writeScanState(root, { ...state, waits: null });
      state = readScanState(root);
    }
    const { open } = withAcceptance(root, att);
    if (!open.length) {
      if (state.cycle && !state.cycle.ended) writeScanState(root, { ...state, cycle: { ...state.cycle, ended: true } });
      return null;
    }
    if ((att.round ?? 0) >= QUALITY_MAX_ROUNDS) {
      if (state.cycle?.budgetReported && state.cycle.id === att.cycle) return null;
      return budgetStop(root, state, att, open, current);
    }
    // Held once per scan: fix them now. The next stop goes through, so the AI
    // can ask the owner about one only they can answer.
    const key = `open:${att.scanId}`;
    // Let through (so the AI can ask the owner), but never silently: the owner
    // sees what is still open.
    if (state.hold?.key === key) return { systemMessage: openSummary(open) };
    writeScanState(root, { ...state, hold: { key, count: 1, at: new Date(now).toISOString() } });
    return ({
      decision: 'block',
      reason:
        `Piezas quality scan: ${open.length} problem(s) are still open (round ${att.round} of ${QUALITY_MAX_ROUNDS}):\n` +
        open.map((f) => `${f.n}. [${f.severity}] ${f.plain}${f.file ? ` (${f.file})` : ''}`).join('\n') +
        '\nFix them now; when you finish, the scan runs again on your fixes. If a fix needs something only the owner has ' +
        '(sample data, a decision), tell them in plain words and ask; they can say "accept" and the number. You cannot accept one yourself. ' +
        'Before a deploy: the scan and its fixes first, then `npx piezas test` LAST on the final code, then deploy.',
    });
  }

  // The code is not scanned as it is now.
  // The budget was used up and reported for exactly this code: nothing new.
  if (state.cycle?.budgetReported && state.cycle.budgetFingerprint === current) return null;
  if (state.cycle && !state.cycle.ended && state.cycle.rounds >= QUALITY_MAX_ROUNDS) {
    const open = att && att.cycle === state.cycle.id ? withAcceptance(root, att).open : [];
    return budgetStop(root, state, att, open, current);
  }
  const built = buildQualityPacket(root, { rulesDir: options.rulesDir, ctx });
  state = readScanState(root);
  const key = `scan:${built.pending.scanId}`;
  // Already let through for this waiting scan ("could not run"): no further
  // hold until the code changes (a new scan).
  if (state.hold?.key === key && state.hold.gaveUp) return null;
  const count = state.hold?.key === key ? state.hold.count : 0;
  if (payload?.stop_hook_active && count >= QUALITY_MAX_HOLDS) {
    // Asked twice and the scan still did not run: let "done" through, say so.
    writeScanState(root, { ...state, hold: { key, count: count + 1, gaveUp: true, at: new Date(now).toISOString() } });
    return ({ systemMessage: QUALITY_TEXT.notRun });
  }
  writeScanState(root, { ...state, hold: { key, count: count + 1, at: new Date(now).toISOString() } });
  return ({
    decision: 'block',
    // The owner's line only when this scan is new, not on a repeat hold.
    ...(count === 0 ? { systemMessage: QUALITY_TEXT.running } : {}),
    reason:
      `Piezas quality scan (round ${built.pending.round} of ${QUALITY_MAX_ROUNDS}), before this step is called done. ` +
      `(The owner has been told it is running.)\n${scannerSteps(root, cli)}\n` +
      'Before a deploy: the scan and its fixes first, then `npx piezas test` LAST on the final code, then deploy.',
  });
}

function openSummary(open) {
  return [QUALITY_TEXT.stillOpen(open.length), ...open.map((f) => `${f.n}. ${f.plain}`), QUALITY_TEXT.stillOpenHint].join('\n');
}

// budgetStop — the third round is used up: "done" goes through, with what is
// still open, once per round of work. The open problems stay open in the
// record (the deploy still asks for them).
function budgetStop(root, state, att, open, current) {
  const cycle = { ...(state.cycle ?? {}), ended: true, budgetReported: true, budgetFingerprint: current };
  writeScanState(root, { ...state, cycle, hold: null, pending: null, waits: null });
  if (!stopReadOnly && att && Array.isArray(att.findings) && att.status !== 'stopped' && open.length) {
    writeJson(join(root, STATE_DIR, QUALITY_ATTESTATION_FILE), { ...att, status: 'stopped', stoppedAfterRounds: att.round ?? QUALITY_MAX_ROUNDS });
  }
  if (!open.length) return null;
  const lines = [QUALITY_TEXT.stopped(QUALITY_MAX_ROUNDS), ...open.map((f) => `${f.n}. ${f.plain}`), QUALITY_TEXT.stoppedHint];
  return ({ systemMessage: lines.join('\n') });
}

// The owner's own terminal command, refused for the AI.
export const QUALITY_OWNER_ONLY_TEXT =
  'This is the owner\'s own choice: they say it in the chat ("quality scan off", "accept 2"), and it is recorded from their own message. ' +
  '(For the AI: never choose for them. Only in a tool without the Piezas checks, relay their exact words: ' +
  'npx piezas quality-scan accept 2 --owner-reply "<their words>".)';

